import { renderToStaticMarkup } from "react-dom/server";
import PortfolioView from "./PortfolioView";

const escapeHtml = (s) =>
  s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

// Produces a single self-contained index.html that can be dropped on any static host.
export function buildPortfolioHtml(data) {
  const { name, title, summary } = data.profile;
  const body = renderToStaticMarkup(<PortfolioView data={data} />);
  const description = escapeHtml((summary || title).slice(0, 160));

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${escapeHtml(name)} – ${escapeHtml(title)}</title>
<meta name="description" content="${description}" />
<script src="https://cdn.tailwindcss.com/3.4.17"></script>
<style>html{scroll-behavior:smooth}</style>
</head>
<body class="bg-[#1c3642]">
${body}
</body>
</html>
`;
}
