export const newItem = (type) =>
  Object.fromEntries(SECTION_TYPES[type].fields.map((f) => [f.key, ""]));

export const createSection = (type) => ({
  id: makeId(),
  type,
  title: SECTION_TYPES[type].title,
  text: "",
  items: SECTION_TYPES[type].kind === "list" ? [newItem(type)] : [],
});

export const EMPTY_PROFILE = {
  name: "",
  title: "",
  email: "",
  phone: "",
  location: "",
  summary: "",
  photo: "",
  linkedin: "",
  github: "",
  website: "",
  resume: "",
};

export const createStarter = () => ({
  profile: { ...EMPTY_PROFILE },
  sections: ["about", "skills", "experience", "projects", "education"].map(createSection),
});

// Rebuilds imported/stored data from known keys only, so a bad file can't break the builder.
export function normalizeData(raw) {
  if (!raw || typeof raw !== "object" || !Array.isArray(raw.sections)) {
    throw new Error("This file is not a portfolio export.");
  }
  const str = (v) => (typeof v === "string" ? v : "");
  const profile = Object.fromEntries(
    Object.keys(EMPTY_PROFILE).map((k) => [k, str(raw.profile?.[k])])
  );
  if (!profile.photo.startsWith("data:image/")) profile.photo = "";

  const sections = raw.sections
    .filter((s) => s && SECTION_TYPES[s.type])
    .map((s) => {
      const def = SECTION_TYPES[s.type];
      return {
        id: str(s.id) || makeId(),
        type: s.type,
        title: str(s.title) || def.title,
        text: str(s.text),
        items:
          def.kind === "list" && Array.isArray(s.items)
            ? s.items.map((item) =>
                Object.fromEntries(def.fields.map((f) => [f.key, str(item?.[f.key])]))
              )
            : [],
      };
    });
  return { profile, sections };
}
