import {
  FaEnvelope,
  FaGithub,
  FaGlobe,
  FaLinkedinIn,
  FaMapMarkerAlt,
  FaPhone,
} from "react-icons/fa";
import { SECTION_TYPES } from "./sectionTypes";
import { isFilled, safeUrl, splitLines, splitList } from "./utils";

const card = "bg-white/10 backdrop-blur-lg border border-white/20 rounded-3xl p-6 md:p-8 text-white";
const chip = "text-xs bg-[#00bcd4]/15 text-[#a5ecf7] border border-[#00bcd4]/30 px-3 py-1 rounded-full";
const backgrounds = [
  "bg-gradient-to-b from-[#2f4f5f] via-[#274754] to-[#1c3642]",
  "bg-gradient-to-b from-[#1c3642] via-[#274754] to-[#2f4f5f]",
];

export const visibleItems = (section) => section.items.filter(isFilled);

export const hasContent = (section) =>
  SECTION_TYPES[section.type].kind === "text"
    ? section.text.trim() !== ""
    : visibleItems(section).length > 0;

const initials = (name) =>
  name.trim().split(/\s+/).slice(0, 2).map((w) => w[0]?.toUpperCase()).join("") || "?";

function Paragraphs({ text }) {
  return text
    .split(/\n\s*\n/)
    .filter((p) => p.trim())
    .map((p, i) => (
      <p key={i} className="text-white/80 leading-7 mb-4 last:mb-0 whitespace-pre-line">
        {p.trim()}
      </p>
    ));
}

function ExternalLink({ href, children, className }) {
  const url = safeUrl(href);
  if (!url) return null;
  return (
    <a href={url} target="_blank" rel="noopener noreferrer" className={className}>
      {children}
    </a>
  );
}

const renderers = {
  about: (s) => (
    <div className={`${card} max-w-4xl mx-auto`}>
      <Paragraphs text={s.text} />
    </div>
  ),
  custom: (s) => renderers.about(s),
  skills: (s) => (
    <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6 max-w-6xl mx-auto">
      {visibleItems(s).map((g, i) => (
        <div key={i} className={card}>
          <h3 className="text-lg font-semibold text-[#67d5eb] mb-4">{g.title}</h3>
          <div className="flex flex-wrap gap-2">
            {splitList(g.skills).map((skill) => (
              <span key={skill} className={chip}>{skill}</span>
            ))}
          </div>
        </div>
      ))}
    </div>
  ),
  experience: (s) => (
    <div className="space-y-8 max-w-5xl mx-auto">
      {visibleItems(s).map((job, i) => (
        <div key={i} className={card}>
          <h3 className="text-xl font-semibold">{job.role}</h3>
          <p className="text-[#00bcd4] font-medium">{job.company}</p>
          <p className="text-sm text-white/60 mb-4">{job.period}</p>
          <ul className="list-disc pl-5 text-white/80 space-y-2">
            {splitLines(job.details).map((d, j) => (
              <li key={j}>{d}</li>
            ))}
          </ul>
        </div>
      ))}
    </div>
  ),
  projects: (s) => (
    <div className="flex flex-wrap gap-8 justify-center max-w-6xl mx-auto">
      {visibleItems(s).map((p, i) => (
        <div key={i} className={`${card} w-full sm:w-[320px] flex flex-col`}>
          <div className="flex gap-2 mb-3 flex-wrap">
            {splitList(p.tech).map((t) => (
              <span key={t} className={chip}>{t}</span>
            ))}
          </div>
          <h3 className="font-semibold text-lg mb-2">{p.title}</h3>
          <p className="text-white/70 text-sm mb-4 flex-1 whitespace-pre-line">{p.description}</p>
          <ExternalLink href={p.link} className="text-sm text-[#67d5eb] hover:underline">
            View project →
          </ExternalLink>
        </div>
      ))}
    </div>
  ),
  education: (s) => (
    <div className="space-y-6 max-w-4xl mx-auto">
      {visibleItems(s).map((e, i) => (
        <div key={i} className={card}>
          <h3 className="text-lg font-semibold">{e.degree}</h3>
          <p className="text-[#00bcd4]">{e.institute}</p>
          <div className="flex flex-wrap justify-between gap-2 text-sm text-white/60 mt-2">
            <span>{e.year}</span>
            <span>{e.score}</span>
          </div>
        </div>
      ))}
    </div>
  ),
  certifications: (s) => (
    <div className="grid sm:grid-cols-2 gap-6 max-w-5xl mx-auto">
      {visibleItems(s).map((c, i) => (
        <div key={i} className={card}>
          <h3 className="font-semibold">{c.name}</h3>
          <p className="text-[#00bcd4] text-sm">{c.issuer}</p>
          <div className="flex justify-between gap-2 text-sm text-white/60 mt-2">
            <span>{c.year}</span>
            <ExternalLink href={c.link} className="text-[#67d5eb] hover:underline">
              Credential →
            </ExternalLink>
          </div>
        </div>
      ))}
    </div>
  ),
};

export default function PortfolioView({ data, editing = false }) {
  const { profile } = data;
  const sections = editing ? data.sections : data.sections.filter(hasContent);
  const name = profile.name.trim() || (editing ? "Your Name" : "");
  const socials = [
    { key: "linkedin", label: "LinkedIn", Icon: FaLinkedinIn },
    { key: "github", label: "GitHub", Icon: FaGithub },
    { key: "website", label: "Website", Icon: FaGlobe },
  ].filter((s) => safeUrl(profile[s.key]));

  return (
    <div className="min-h-full bg-[#1c3642] font-sans">
      <nav className="sticky top-0 z-40 bg-[#2f4f5f] border-b border-white/10">
        <div className="flex items-center gap-6 px-6 py-4">
          <a href="#home" className="text-lg font-semibold text-white shrink-0">{name}</a>
          <ul className="flex gap-5 text-sm ml-auto overflow-x-auto whitespace-nowrap">
            {sections.map((s) => (
              <li key={s.id}>
                <a href={`#s-${s.id}`} className="text-white hover:text-[#00bcd4]">{s.title}</a>
              </li>
            ))}
            <li>
              <a href="#contact" className="text-white hover:text-[#00bcd4]">Contact</a>
            </li>
          </ul>
        </div>
      </nav>

      <section id="home" className="relative overflow-hidden min-h-[80vh] flex items-center px-6 md:px-16 py-20 bg-[#2f4f5f]">
        <div className="absolute top-20 left-10 w-80 h-80 bg-[#67d5eb]/15 rounded-full blur-3xl" />
        <div className="absolute bottom-10 right-10 w-80 h-80 bg-[#00bcd4]/15 rounded-full blur-3xl" />
        <div className="relative z-10 grid md:grid-cols-2 gap-12 items-center w-full max-w-6xl mx-auto">
          <div className="order-2 md:order-1">
            <h1 className="text-4xl md:text-5xl font-bold text-white">
              Hi, I’m <span className="text-[#67d5eb]">{name}</span>
            </h1>
            <p className="mt-3 text-lg text-[#00bcd4] font-medium">
              {profile.title || (editing ? "Your headline" : "")}
            </p>
            {profile.summary && (
              <p className="mt-6 text-white/80 max-w-xl whitespace-pre-line">{profile.summary}</p>
            )}
            <div className="mt-8 flex gap-4 flex-wrap">
              <a href="#contact" className="bg-[#00bcd4] text-[#2f4f5f] px-6 py-3 rounded-xl font-medium hover:bg-[#67d5eb]">
                Contact Me
              </a>
              <ExternalLink
                href={profile.resume}
                className="border border-[#67d5eb] text-[#67d5eb] px-6 py-3 rounded-xl hover:bg-[#67d5eb] hover:text-[#2f4f5f]"
              >
                Download CV
              </ExternalLink>
            </div>
          </div>
          <div className="order-1 md:order-2 relative flex justify-center">
            <div className="absolute w-72 h-72 bg-[#00bcd4]/20 rounded-full blur-2xl" />
            {profile.photo ? (
              <img
                src={profile.photo}
                alt={name}
                className="relative w-56 h-56 md:w-72 md:h-72 rounded-full object-cover object-top border-4 border-white shadow-xl"
              />
            ) : (
              <div className="relative w-56 h-56 md:w-72 md:h-72 rounded-full border-4 border-white shadow-xl bg-[#274754] flex items-center justify-center text-6xl font-bold text-[#67d5eb]">
                {initials(name)}
              </div>
            )}
          </div>
        </div>
      </section>

      {sections.map((s, i) => (
        <section key={s.id} id={`s-${s.id}`} className={`scroll-mt-16 px-6 md:px-16 py-20 ${backgrounds[i % 2]}`}>
          <h2 className="text-3xl font-bold text-center text-white mb-10">{s.title}</h2>
          {hasContent(s) ? (
            renderers[s.type](s)
          ) : (
            <p className="text-center text-white/50 italic">
              This section is empty and will be hidden on your published site.
            </p>
          )}
        </section>
      ))}

      <footer id="contact" className="scroll-mt-16 bg-gradient-to-b from-[#355f6d] to-[#0f1b2d] text-white pt-20 pb-8 px-6 text-center">
        <h2 className="text-2xl md:text-3xl font-bold mb-3">
          Let’s <span className="text-[#67d5eb]">work together</span>
        </h2>
        {profile.email && (
          <a
            href={`mailto:${profile.email.trim()}`}
            className="inline-flex items-center gap-2 bg-[#00bcd4] text-[#1c3642] px-6 py-3 rounded-xl font-medium hover:bg-[#67d5eb] my-6"
          >
            <FaEnvelope aria-hidden="true" /> Email Me
          </a>
        )}
        <div className="text-sm text-white/80 space-y-2 mb-6">
          {profile.email && <p>{profile.email}</p>}
          {profile.phone && (
            <p className="inline-flex items-center gap-2"><FaPhone aria-hidden="true" /> {profile.phone}</p>
          )}
          {profile.location && (
            <p className="flex items-center justify-center gap-2"><FaMapMarkerAlt aria-hidden="true" /> {profile.location}</p>
          )}
        </div>
        {socials.length > 0 && (
          <div className="flex justify-center gap-4 mb-6">
            {socials.map(({ key, label, Icon }) => (
              <a
                key={key}
                href={safeUrl(profile[key])}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={label}
                className="border border-white/30 p-2 rounded-md hover:border-[#00bcd4] hover:text-[#00bcd4]"
              >
                <Icon size={16} />
              </a>
            ))}
          </div>
        )}
        <p className="text-xs text-white/50">
          © {new Date().getFullYear()} {name}. All rights reserved.
        </p>
      </footer>
    </div>
  );
}
