import { useEffect, useRef, useState } from "react";
import {
  FaArrowDown,
  FaArrowLeft,
  FaArrowUp,
  FaCamera,
  FaChevronDown,
  FaDownload,
  FaFileExport,
  FaFileImport,
  FaPlus,
  FaTrash,
} from "react-icons/fa";
import PortfolioView from "./PortfolioView";
import { buildPortfolioHtml } from "./exportHtml";
import { SECTION_TYPES, createSection, createStarter, newItem, normalizeData } from "./sectionTypes";
import { downloadFile, resizeImage, validateProfile } from "./utils";

const STORAGE_KEY = "portfolio-builder:v1";
const MAX_UPLOAD_MB = 8;

const input =
  "w-full bg-white/5 border border-white/15 rounded-lg px-3 py-2 text-sm text-white placeholder-white/30 focus:outline-none focus:border-[#00bcd4]";
const btn = "inline-flex items-center gap-2 px-3 py-2 rounded-lg text-sm transition";
const iconBtn = "p-2 rounded-md text-white/60 hover:text-white hover:bg-white/10 disabled:opacity-30 disabled:hover:bg-transparent";

function loadData() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) return normalizeData(JSON.parse(saved));
  } catch {
    // Unreadable or blocked storage: start fresh.
  }
  return createStarter();
}

function Field({ label, required, error, textarea, ...props }) {
  const Tag = textarea ? "textarea" : "input";
  return (
    <label className="block">
      <span className="block text-xs text-white/70 mb-1">
        {label} {required && <span className="text-red-400">*</span>}
      </span>
      <Tag
        {...props}
        rows={textarea ? 4 : undefined}
        aria-invalid={!!error}
        className={`${input} ${error ? "border-red-400" : ""}`}
      />
      {error && <span className="block text-xs text-red-400 mt-1">{error}</span>}
    </label>
  );
}

function ProfileEditor({ profile, errors, showError, onChange, onTouch }) {
  const fileRef = useRef(null);
  const [photoError, setPhotoError] = useState("");

  const onPhoto = async (e) => {
    const file = e.target.files[0];
    e.target.value = "";
    if (!file) return;
    if (!file.type.startsWith("image/")) return setPhotoError("Please choose an image file.");
    if (file.size > MAX_UPLOAD_MB * 1024 * 1024) return setPhotoError(`Image must be under ${MAX_UPLOAD_MB} MB.`);
    try {
      onChange("photo", await resizeImage(file));
      setPhotoError("");
    } catch (err) {
      setPhotoError(err.message);
    }
  };

  const field = (key, label, opts = {}) => (
    <Field
      label={label}
      value={profile[key]}
      error={showError(key) ? errors[key] : ""}
      onChange={(e) => onChange(key, e.target.value)}
      onBlur={() => onTouch(key)}
      {...opts}
    />
  );

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-4">
        <button
          type="button"
          onClick={() => fileRef.current.click()}
          className={`relative w-20 h-20 rounded-full overflow-hidden border-2 shrink-0 flex items-center justify-center bg-white/5
            ${showError("photo") && errors.photo ? "border-red-400" : "border-[#00bcd4]/50"}`}
          aria-label="Upload profile photo"
        >
          {profile.photo ? (
            <img src={profile.photo} alt="Profile preview" className="w-full h-full object-cover object-top" />
          ) : (
            <FaCamera className="text-white/40" size={22} />
          )}
        </button>
        <div className="text-sm">
          <p className="text-white/70 text-xs mb-2">
            Profile photo <span className="text-red-400">*</span>
          </p>
          <div className="flex gap-2">
            <button type="button" onClick={() => fileRef.current.click()} className={`${btn} bg-white/10 text-white hover:bg-white/20`}>
              {profile.photo ? "Change" : "Upload photo"}
            </button>
            {profile.photo && (
              <button type="button" onClick={() => onChange("photo", "")} className={`${btn} text-red-300 hover:bg-red-500/10`}>
                Remove
              </button>
            )}
          </div>
          {(photoError || (showError("photo") && errors.photo)) && (
            <p className="text-xs text-red-400 mt-1">{photoError || errors.photo}</p>
          )}
        </div>
        <input ref={fileRef} type="file" accept="image/*" hidden onChange={onPhoto} />
      </div>

      {field("name", "Full name", { required: true, placeholder: "Jane Doe" })}
      {field("title", "Headline", { required: true, placeholder: "Software Engineer · React · Node.js" })}
      {field("email", "Email", { required: true, type: "email", placeholder: "jane@example.com" })}
      <div className="grid grid-cols-2 gap-3">
        {field("phone", "Phone", { placeholder: "+91 ..." })}
        {field("location", "Location", { placeholder: "Bengaluru, India" })}
      </div>
      {field("summary", "Short intro", { textarea: true, placeholder: "One or two lines shown under your name" })}
      {field("linkedin", "LinkedIn URL", { placeholder: "https://linkedin.com/in/..." })}
      {field("github", "GitHub URL", { placeholder: "https://github.com/..." })}
      {field("website", "Website", { placeholder: "https://..." })}
      {field("resume", "Resume / CV link", { placeholder: "https://drive.google.com/..." })}
    </div>
  );
}

function SectionEditor({ section, index, count, onUpdate, onMove, onRemove }) {
  const [open, setOpen] = useState(false);
  const def = SECTION_TYPES[section.type];

  const setItem = (i, key, value) =>
    onUpdate({ items: section.items.map((it, j) => (j === i ? { ...it, [key]: value } : it)) });

  return (
    <div className="bg-white/5 border border-white/10 rounded-xl">
      <div className="flex items-center gap-1 p-2">
        <button
          type="button"
          onClick={() => setOpen(!open)}
          aria-expanded={open}
          className="flex-1 flex items-center gap-2 text-left px-2 py-1 min-w-0"
        >
          <FaChevronDown className={`text-white/50 shrink-0 transition ${open ? "" : "-rotate-90"}`} size={12} />
          <span className="text-white text-sm font-medium truncate">{section.title || def.label}</span>
          <span className="text-[10px] uppercase tracking-wider text-[#67d5eb]/70 shrink-0">{def.label}</span>
        </button>
        <button type="button" className={iconBtn} disabled={index === 0} onClick={() => onMove(-1)} aria-label="Move section up">
          <FaArrowUp size={12} />
        </button>
        <button type="button" className={iconBtn} disabled={index === count - 1} onClick={() => onMove(1)} aria-label="Move section down">
          <FaArrowDown size={12} />
        </button>
        <button type="button" className={`${iconBtn} hover:text-red-300`} onClick={onRemove} aria-label={`Remove ${section.title} section`}>
          <FaTrash size={12} />
        </button>
      </div>

      {open && (
        <div className="px-4 pb-4 space-y-4 border-t border-white/10 pt-4">
          <Field label="Section title" value={section.title} onChange={(e) => onUpdate({ title: e.target.value })} />

          {def.kind === "text" ? (
            <Field label="Content" textarea value={section.text} placeholder={def.placeholder} onChange={(e) => onUpdate({ text: e.target.value })} />
          ) : (
            <>
              {section.items.map((item, i) => (
                <div key={i} className="border border-white/10 rounded-lg p-3 space-y-3">
                  <div className="flex justify-between items-center">
                    <span className="text-xs text-white/50">{def.itemLabel} {i + 1}</span>
                    <button
                      type="button"
                      onClick={() => onUpdate({ items: section.items.filter((_, j) => j !== i) })}
                      className="text-xs text-red-300 hover:underline"
                    >
                      Remove
                    </button>
                  </div>
                  {def.fields.map((f) => (
                    <Field
                      key={f.key}
                      label={f.label}
                      textarea={f.type === "textarea"}
                      placeholder={f.placeholder}
                      value={item[f.key]}
                      onChange={(e) => setItem(i, f.key, e.target.value)}
                    />
                  ))}
                </div>
              ))}
              <button
                type="button"
                onClick={() => onUpdate({ items: [...section.items, newItem(section.type)] })}
                className={`${btn} w-full justify-center border border-dashed border-white/20 text-white/70 hover:text-white hover:border-[#00bcd4]`}
              >
                <FaPlus size={10} /> Add {def.itemLabel.toLowerCase()}
              </button>
            </>
          )}
        </div>
      )}
    </div>
  );
}

function HostingDialog({ onClose }) {
  return (
    <div className="fixed inset-0 z-50 bg-black/60 flex items-center justify-center p-4" onClick={onClose}>
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby="host-title"
        onClick={(e) => e.stopPropagation()}
        className="bg-[#1c3642] border border-white/15 rounded-2xl p-6 max-w-lg w-full text-white"
      >
        <h2 id="host-title" className="text-xl font-semibold mb-1">Your site is downloaded 🎉</h2>
        <p className="text-sm text-white/70 mb-5">
          <code className="text-[#67d5eb]">index.html</code> is a complete website. Put it online for free:
        </p>
        <div className="space-y-4 text-sm">
          <div>
            <h3 className="font-semibold text-[#67d5eb]">Netlify Drop (fastest, no account needed to try)</h3>
            <ol className="list-decimal pl-5 text-white/80 space-y-1 mt-1">
              <li>Open <a className="underline" href="https://app.netlify.com/drop" target="_blank" rel="noopener noreferrer">app.netlify.com/drop</a></li>
              <li>Drag the downloaded <code>index.html</code> onto the page</li>
              <li>Netlify gives you a live link right away</li>
            </ol>
          </div>
          <div>
            <h3 className="font-semibold text-[#67d5eb]">GitHub Pages</h3>
            <ol className="list-decimal pl-5 text-white/80 space-y-1 mt-1">
              <li>Create a public repo named <code>your-username.github.io</code></li>
              <li>Upload <code>index.html</code> to it</li>
              <li>Your site goes live at <code>https://your-username.github.io</code></li>
            </ol>
          </div>
          <p className="text-white/60">
            Tip: use <strong>Export data</strong> to save your content, so you can import it later and keep editing.
          </p>
        </div>
        <button onClick={onClose} className={`${btn} mt-6 bg-[#00bcd4] text-[#1c3642] font-medium hover:bg-[#67d5eb]`}>
          Got it
        </button>
      </div>
    </div>
  );
}

export default function Builder() {
  const [data, setData] = useState(loadData);
  const [touched, setTouched] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [notice, setNotice] = useState("");
  const [showHosting, setShowHosting] = useState(false);
  const [mobileView, setMobileView] = useState("edit");
  const importRef = useRef(null);
  const profileRef = useRef(null);

  const errors = validateProfile(data.profile);
  const ready = Object.keys(errors).length === 0;
  const showError = (key) => submitted || touched[key];

  useEffect(() => {
    document.title = "Portfolio Builder";
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    } catch {
      setNotice("Couldn't save to this browser. Use Export data to keep a copy.");
    }
  }, [data]);

  const setProfile = (key, value) =>
    setData((d) => ({ ...d, profile: { ...d.profile, [key]: value } }));

  const updateSection = (id, patch) =>
    setData((d) => ({ ...d, sections: d.sections.map((s) => (s.id === id ? { ...s, ...patch } : s)) }));

  const moveSection = (index, dir) =>
    setData((d) => {
      const sections = [...d.sections];
      [sections[index], sections[index + dir]] = [sections[index + dir], sections[index]];
      return { ...d, sections };
    });

  const removeSection = (section) => {
    if (!window.confirm(`Remove the "${section.title}" section?`)) return;
    setData((d) => ({ ...d, sections: d.sections.filter((s) => s.id !== section.id) }));
  };

  const addSection = (type) =>
    setData((d) => ({ ...d, sections: [...d.sections, createSection(type)] }));

  const requireProfile = () => {
    if (ready) return true;
    setSubmitted(true);
    setMobileView("edit");
    setNotice("Complete the required profile fields (marked *) first.");
    profileRef.current?.scrollIntoView({ behavior: "smooth" });
    return false;
  };

  const downloadSite = () => {
    if (!requireProfile()) return;
    downloadFile("index.html", buildPortfolioHtml(data), "text/html");
    setNotice("");
    setShowHosting(true);
  };

  const exportData = () => downloadFile("portfolio-data.json", JSON.stringify(data, null, 2), "application/json");

  const importData = async (e) => {
    const file = e.target.files[0];
    e.target.value = "";
    if (!file) return;
    try {
      setData(normalizeData(JSON.parse(await file.text())));
      setNotice("Portfolio data imported.");
    } catch (err) {
      setNotice(err instanceof SyntaxError ? "That file isn't valid JSON." : err.message);
    }
  };

  const reset = () => {
    if (!window.confirm("Clear everything and start over? This can't be undone.")) return;
    setData(createStarter());
    setTouched({});
    setSubmitted(false);
  };

  // Keep in-page anchor clicks inside the preview pane instead of changing the builder's URL hash.
  const onPreviewClick = (e) => {
    const link = e.target.closest('a[href^="#"]');
    if (!link) return;
    e.preventDefault();
    e.currentTarget.querySelector(link.getAttribute("href"))?.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <div className="h-screen flex flex-col bg-[#0f1b2d] text-white">
      <header className="flex flex-wrap items-center gap-2 px-4 py-3 bg-[#2f4f5f] border-b border-white/10">
        <a href="#/" className={`${iconBtn} mr-1`} aria-label="Back to portfolio">
          <FaArrowLeft size={14} />
        </a>
        <h1 className="font-semibold mr-auto">
          Portfolio <span className="text-[#67d5eb]">Builder</span>
        </h1>
        <span className={`text-xs px-2 py-1 rounded-full ${ready ? "bg-green-500/20 text-green-300" : "bg-amber-500/20 text-amber-300"}`}>
          {ready ? "Ready to publish" : "Profile incomplete"}
        </span>
        <button onClick={() => importRef.current.click()} className={`${btn} text-white/80 hover:bg-white/10`}>
          <FaFileImport /> <span className="hidden sm:inline">Import</span>
        </button>
        <button onClick={exportData} className={`${btn} text-white/80 hover:bg-white/10`}>
          <FaFileExport /> <span className="hidden sm:inline">Export data</span>
        </button>
        <button onClick={reset} className={`${btn} text-white/60 hover:bg-white/10`}>Reset</button>
        <button onClick={downloadSite} className={`${btn} bg-[#00bcd4] text-[#1c3642] font-medium hover:bg-[#67d5eb]`}>
          <FaDownload /> Download website
        </button>
        <input ref={importRef} type="file" accept="application/json,.json" hidden onChange={importData} />
      </header>

      {notice && (
        <div role="status" className="flex justify-between gap-4 px-4 py-2 text-sm bg-amber-500/15 text-amber-200">
          <span>{notice}</span>
          <button onClick={() => setNotice("")} aria-label="Dismiss" className="text-amber-200/70 hover:text-amber-100">✕</button>
        </div>
      )}

      <div className="lg:hidden flex border-b border-white/10">
        {["edit", "preview"].map((v) => (
          <button
            key={v}
            onClick={() => setMobileView(v)}
            aria-pressed={mobileView === v}
            className={`flex-1 py-2 text-sm capitalize ${mobileView === v ? "text-[#00bcd4] border-b-2 border-[#00bcd4]" : "text-white/60"}`}
          >
            {v}
          </button>
        ))}
      </div>

      <div className="flex-1 flex min-h-0">
        <aside className={`${mobileView === "edit" ? "block" : "hidden"} lg:block w-full lg:w-[420px] shrink-0 overflow-y-auto p-4 space-y-6 border-r border-white/10`}>
          <section ref={profileRef} className="bg-white/5 border border-white/10 rounded-xl p-4">
            <div className="flex items-center justify-between mb-4">
              <h2 className="font-semibold">Profile</h2>
              <span className="text-[10px] uppercase tracking-wider bg-red-500/20 text-red-300 px-2 py-0.5 rounded">Required</span>
            </div>
            <ProfileEditor
              profile={data.profile}
              errors={errors}
              showError={showError}
              onChange={setProfile}
              onTouch={(key) => setTouched((t) => ({ ...t, [key]: true }))}
            />
          </section>

          <section>
            <h2 className="font-semibold mb-1">Sections</h2>
            <p className="text-xs text-white/50 mb-3">Click a section to edit it. Reorder or remove as you like; empty sections are left out of your site.</p>
            <div className="space-y-2">
              {data.sections.map((s, i) => (
                <SectionEditor
                  key={s.id}
                  section={s}
                  index={i}
                  count={data.sections.length}
                  onUpdate={(patch) => updateSection(s.id, patch)}
                  onMove={(dir) => moveSection(i, dir)}
                  onRemove={() => removeSection(s)}
                />
              ))}
              {data.sections.length === 0 && (
                <p className="text-sm text-white/50 text-center py-4">No sections yet. Add one below.</p>
              )}
            </div>

            <h3 className="text-xs text-white/60 mt-5 mb-2">Add a section</h3>
            <div className="flex flex-wrap gap-2">
              {Object.entries(SECTION_TYPES).map(([type, def]) => (
                <button
                  key={type}
                  onClick={() => addSection(type)}
                  className={`${btn} py-1.5 bg-white/5 border border-white/15 text-white/80 hover:border-[#00bcd4] hover:text-white`}
                >
                  <FaPlus size={10} /> {def.label}
                </button>
              ))}
            </div>
          </section>
        </aside>

        <main
          onClick={onPreviewClick}
          aria-label="Live preview"
          className={`${mobileView === "preview" ? "block" : "hidden"} lg:block flex-1 overflow-y-auto`}
        >
          <PortfolioView data={data} editing />
        </main>
      </div>

      {showHosting && <HostingDialog onClose={() => setShowHosting(false)} />}
    </div>
  );
}
