export const makeId = () =>
  Date.now().toString(36) + Math.random().toString(36).slice(2, 7);

export const splitList = (value = "") =>
  value.split(",").map((s) => s.trim()).filter(Boolean);

export const splitLines = (value = "") =>
  value.split("\n").map((s) => s.trim()).filter(Boolean);

export const isFilled = (item) =>
  Object.values(item).some((v) => typeof v === "string" && v.trim() !== "");

// Only allow links that are safe to put in an href; bare domains get https://.
export const safeUrl = (value = "") => {
  const url = value.trim();
  if (!url) return "";
  if (/^(https?:|mailto:|tel:)/i.test(url)) return url;
  if (/^[\w.-]+\.[a-z]{2,}(\/.*)?$/i.test(url)) return `https://${url}`;
  return "";
};

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function validateProfile(profile) {
  const errors = {};
  if (!profile.name.trim()) errors.name = "Full name is required";
  if (!profile.title.trim()) errors.title = "Headline is required";
  if (!profile.email.trim()) errors.email = "Email is required";
  else if (!EMAIL_RE.test(profile.email.trim())) errors.email = "Enter a valid email";
  if (!profile.photo) errors.photo = "Profile photo is required";
  ["linkedin", "github", "website", "resume"].forEach((key) => {
    if (profile[key].trim() && !safeUrl(profile[key])) errors[key] = "Enter a valid link";
  });
  return errors;
}

// Downscale uploads so the photo fits comfortably in localStorage and the exported HTML.
export function resizeImage(file, max = 640) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Could not read that file."));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("That file is not a valid image."));
      img.onload = () => {
        const scale = Math.min(1, max / Math.max(img.width, img.height));
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        const ctx = canvas.getContext("2d");
        ctx.fillStyle = "#ffffff";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/jpeg", 0.85));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

export function downloadFile(filename, content, type) {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}
